<?php require_once 'includes/config.php'; require_teacher(); $tid=current_teacher_id();
$q=$dbh->prepare('SELECT s.StudentId,s.StudentName,s.RollId,c.id AS ClassId,c.ClassName,c.Section, COALESCE(rs.submission_status,\'draft\') AS submission_status, rs.academic_year,rs.exam_type FROM teacher_student_assignments a JOIN tblstudents s ON s.StudentId=a.student_id JOIN tblclasses c ON c.id=a.class_id LEFT JOIN result_submissions rs ON rs.teacher_id=a.teacher_id AND rs.student_id=a.student_id AND rs.class_id=a.class_id WHERE a.teacher_id=:t ORDER BY c.ClassNameNumeric,c.Section,s.StudentName');$q->execute([':t'=>$tid]);$rows=$q->fetchAll();
